import os,json,subprocess,re,datetime
from pathlib import Path
src=Path("/var/www/lowcost-europa");root=Path("/srv/projects/lowcost-europa");dst=root/"www"
out={"phase":"lowcost-public-www","status":"BLOCKED","changed":False,"at":datetime.datetime.now(datetime.timezone.utc).isoformat()}
def ok(args):
 try:return subprocess.run(args,capture_output=True,text=True,timeout=10).returncode==0
 except Exception:return False
try:
 if not root.is_dir() or root.is_symlink() or not src.is_dir() or src.is_symlink() or dst.exists() or dst.is_symlink():raise RuntimeError("path_preflight_failed")
 original=src.stat()
 if original.st_dev!=root.stat().st_dev:raise RuntimeError("cross_filesystem")
 if not ok(["nginx","-t"]):raise RuntimeError("nginx_preflight_failed")
 if not ok(["runuser","-u","www-data","--","test","-x",str(root)]):raise RuntimeError("nginx_cannot_traverse_project_root")
 for base in (Path("/etc/nginx/nginx.conf"),*Path("/etc/nginx/sites-available").glob("*")):
  try:
   content=base.read_text()
   if re.search(r"^\s*disable_symlinks\s+(on|if_not_owner)\b",content,re.M):raise RuntimeError("nginx_symlinks_disabled")
  except (OSError,UnicodeError):pass
 def service_state():
  return {name:subprocess.run(["systemctl","is-active",name],capture_output=True,text=True,timeout=6).stdout.strip() for name in ("nginx","lowcost-europa","fadego-staging","pink-iptv-backend","pm2-root","ssh")}
 before=service_state()
 if not ok(["runuser","-u","www-data","--","test","-r",str(src/"aliexpress")]):raise RuntimeError("old_web_content_unreadable")
 os.rename(src,dst)
 moved=True
 try:
  os.symlink(str(dst),src)
  verify=dst.stat()
  if not src.is_symlink() or src.resolve(strict=True)!=dst or dst.is_symlink() or not dst.is_dir() or verify.st_ino!=original.st_ino or verify.st_dev!=original.st_dev or verify.st_uid!=original.st_uid or verify.st_gid!=original.st_gid:
   raise RuntimeError("physical_identity_postcheck_failed")
  if not ok(["runuser","-u","www-data","--","test","-r",str(src/"aliexpress")]):raise RuntimeError("legacy_web_path_unreadable")
  if not ok(["runuser","-u","www-data","--","test","-r",str(dst/"aliexpress")]):raise RuntimeError("canonical_web_path_unreadable")
  if not ok(["nginx","-t"]):raise RuntimeError("nginx_postcheck_failed")
  if service_state()!=before:raise RuntimeError("service_state_changed")
  out.update(status="MOVED_AND_VERIFIED",changed=True,root=str(dst),legacy_alias=str(src),inode_preserved=True,owner_preserved=True,www_data_can_access=True,nginx_config_pass=True,services_unchanged=True)
 except Exception:
  if src.is_symlink() and src.resolve(strict=False)==dst:src.unlink()
  if moved and dst.is_dir() and not src.exists() and not src.is_symlink():os.rename(dst,src)
  raise
except Exception as e:out["reason"]=str(e)[:200]
print(json.dumps(out,sort_keys=True))
if out["status"]!="MOVED_AND_VERIFIED":raise SystemExit(3)
